12	func (d *DB) UpsertReaction(ctx context.Context, upsert *store.Reaction) (*store.Reaction, error) {
13		fields := []string{"`creator_id`", "`content_id`", "`reaction_type`"}
14		placeholder := []string{"?", "?", "?"}
15		args := []interface{}{upsert.CreatorID, upsert.ContentID, upsert.ReactionType}
16		stmt := "INSERT INTO `reaction` (" + strings.Join(fields, ", ") + ") VALUES (" + strings.Join(placeholder, ", ") + ") RETURNING `id`, `created_ts`"
17		if err := d.db.QueryRowContext(ctx, stmt, args...).Scan(
18			&upsert.ID,
19			&upsert.CreatedTs,
20		); err != nil {
21			return nil, err
22		}
23	
24		reaction := upsert
25		return reaction, nil
26	}
