28	func (d *DB) ListReactions(ctx context.Context, find *store.FindReaction) ([]*store.Reaction, error) {
29		where, args := []string{"1 = 1"}, []any{}
30	
31		if find.ID != nil {
32			where, args = append(where, "id = ?"), append(args, *find.ID)
